#include "stdlib/blas/ext/base/sindex_of_greater_than_sorted.h"
#include "stdlib/strided/base/stride2offset.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/blas/base/shared.h"

/**
* Returns the index of the first element in a sorted single-precision floating-point strided array which is greater than a specified search element.
*
* @param N             number of indexed elements
* @param searchElement search element
* @param X             sorted input array
* @param strideX       stride length
* @return              index
*/
CBLAS_INT API_SUFFIX(stdlib_strided_sindex_of_greater_than_sorted)( const CBLAS_INT N, const float searchElement, const float *X, const CBLAS_INT strideX ) {
	CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	return API_SUFFIX(stdlib_strided_sindex_of_greater_than_sorted_ndarray)( N, searchElement, X, strideX, ox );
}

/**
* Returns the index of the first element in a sorted single-precision floating-point strided array which is greater than a specified search element using alternative indexing semantics.
*
* @param N             number of indexed elements
* @param searchElement search element
* @param X             sorted input array
* @param strideX       stride length
* @param offsetX       starting index
* @return              index
*/
CBLAS_INT API_SUFFIX(stdlib_strided_sindex_of_greater_than_sorted_ndarray)( const CBLAS_INT N, const float searchElement, const float *X, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
	CBLAS_INT mid;
	CBLAS_INT lo;
	CBLAS_INT hi;
	CBLAS_INT ix;
	CBLAS_INT i;
	float v1;
	float v2;
	float v;

	if ( N <= 0 ) {
		return -1;
	}
	v1 = X[ offsetX ];
	v2 = X[ offsetX + ( ( N - 1 ) * strideX ) ];

	// If either the first or last indexed element is NaN, we cannot determine the sort order, so fall back to a linear search...
	if ( stdlib_base_is_nan( v1 ) || stdlib_base_is_nan( v2 ) ) {
		lo = 0;
	} else {
		// Descending order: elements which are greater than the search element form a prefix, so only the first indexed element needs to be checked...
		if ( v1 >= v2 ) {
			if ( v1 > searchElement ) {
				return 0;
			}
			return -1;
		}
		// Ascending order: perform a binary search for the first element which is greater than the search element...
		lo = 0;
		hi = N;
		while ( lo < hi ) {
			mid = lo + ( ( hi - lo ) / 2 );
			v = X[ offsetX + ( mid * strideX ) ];

			// If we encounter a NaN, fall back to a linear search...
			if ( stdlib_base_is_nan( v ) ) {
				break;
			}
			if ( searchElement < v ) {
				hi = mid;
			} else {
				lo = mid + 1;
			}
		}
		if ( lo == hi ) {
			if ( lo == N ) {
				return -1;
			}
			return lo;
		}
	}
	// Linear search over the remaining candidate elements...
	ix = offsetX + ( lo * strideX );
	for ( i = lo; i < N; i++ ) {
		if ( X[ ix ] > searchElement ) {
			return i;
		}
		ix += strideX;
	}
	return -1;
}
